/// GET v1/publishers/{publishersId}/models/{modelsId}
/// Gets a Model Garden publisher model.
///
/// Returns `ClientRequestBuilder` for customization.
/// Use `aiplatform_publishers_models_get_execute()` to send, or `aiplatform_publishers_models_get` for simplest API.

pub fn aiplatform_publishers_models_get_builder<R>(
    client: &SimpleHttpClient<R>,
    name: &String,
    huggingFaceToken: &Option<String>,
    isHuggingFaceModel: &Option<String>,
    languageCode: &Option<String>,
    view: &Option<String>,
) -> Result<ClientRequestBuilder<R>, ApiError>
where
    R: DnsResolver + Clone,
{
    // Build URL
    let endpoint_url = format!(
        "https://aiplatform.googleapis.com/v1/publishers/{}/models/{modelsId}",
        name,
    );

    // Build request
    let mut query_parts = Vec::new();
    if let Some(val) = huggingFaceToken.as_ref() {
        query_parts.push(format!("huggingFaceToken={}", val));
    }
    if let Some(val) = isHuggingFaceModel.as_ref() {
        query_parts.push(format!("isHuggingFaceModel={}", val));
    }
    if let Some(val) = languageCode.as_ref() {
        query_parts.push(format!("languageCode={}", val));
    }
    if let Some(val) = view.as_ref() {
        query_parts.push(format!("view={}", val));
    }

    let url_with_query = if query_parts.is_empty() {
        endpoint_url
    } else {
        format!("{}?{}", endpoint_url, query_parts.join("&"))
    };

    let builder = client
        .get(&url_with_query)
        .map_err(|e| ApiError::RequestBuildFailed(e.to_string()))?;

    Ok(builder)
}

